static unsigned checks=0;static void Check(bool ok,const std::string& reason){if(!ok)throw std::runtime_error(reason);++checks;std::cerr<<checks<<": "<<reason<<'\n';}
struct Files {fs::path dir=AssetPaths::GetExecutableDirectory()/("viewmodel_"+NewSceneIdentity());std::shared_ptr<const ProjectContext> old=ProjectManager::Active(),project;Files(){Check(dir.parent_path()==AssetPaths::GetExecutableDirectory()&&fs::create_directory(dir),"owned fixture");project=ProjectManager::Create(dir,"Viewmodel");ProjectManager::Activate(project);}~Files(){ProjectManager::Activate(old);scripting::ClearPrefabCache();if(dir.parent_path()==AssetPaths::GetExecutableDirectory()){std::error_code error;fs::remove_all(dir,error);}}};
static Entity Node(World& w,MeshRenderMode mode=MeshRenderMode::World){auto e=w.CreateEntity();w.AddComponent<TransformComponent>(e);w.AddComponent<SceneIdentityComponent>(e);auto& mesh=w.AddComponent<MeshRendererComponent>(e);mesh.meshPath="@engine/models/primitives/cube.obj";mesh.renderMode=mode;return e;}
struct Recorder:IRenderAdapter {int pass=0;unsigned world=0,viewmodel=0,shadows=0,begins=0;std::uint64_t next=1;bool Initialize(IWindow*)override{return true;}void BeginFrame()override{world=viewmodel=shadows=begins=0;}void Clear(float,float,float,float)override{}void SetTestTransform(const float*)override{}void SetTestColor(float,float,float,float)override{}void DrawTestTriangle()override{}void DrawTestLine()override{}void DrawTestQuad()override{}void DrawTestCube()override{}void EndFrame()override{}void Present()override{}void Shutdown()override{}RenderMeshHandle UploadMesh(const MeshData&)override{return {next++};}RenderTextureHandle CreateTexture2D(const TextureData&)override{return {next++};}RenderShaderHandle CreateShaderProgram(const ShaderResource&)override{return {next++};}void BeginMainPass()override{pass=0;}bool BeginViewmodelPass()override{pass=1;++begins;return true;}void EndViewmodelPass()override{pass=0;}void DrawMesh(RenderMeshHandle)override{if(pass)++viewmodel;else ++world;}bool BeginShadowPass(const ShadowFrame&)override{return true;}void DrawShadowMesh(RenderMeshHandle,const RenderInstanceData&)override{++shadows;}};
static void Cpu(){Files files;World w;auto wall=Node(w),weapon=Node(w,MeshRenderMode::FirstPerson),part=Node(w,MeshRenderMode::FirstPerson);Check(w.SetParent(part,weapon,false),"weapon hierarchy");ResourceManager rm(nullptr);Recorder gpu;RenderSystem renderer;renderer.SetRenderAdapter(&gpu);renderer.SetResourceManager(&rm);for(int n=0;n<15;++n){gpu.BeginFrame();renderer.Update(w,0);rm.DrainProjectLoads();}Check(gpu.world==1&&gpu.viewmodel==2&&gpu.begins==1,"World and FirstPerson classification without duplicate submission");Check(gpu.shadows==1,"viewmodels excluded from world shadows");Check(renderer.GetStatistics().worldSubmeshes==1&&renderer.GetStatistics().viewmodelSubmeshes==2,"shared submission counters");
 auto scene=SceneSerializer::CaptureWorld(w);World restored;SceneSettings settings;std::string error;Check(SceneSerializer::RestoreWorld(scene,restored,settings,&error),error);unsigned count=0;for(auto e:restored.Entities())if(restored.GetComponent<MeshRendererComponent>(e)->renderMode==MeshRenderMode::FirstPerson)++count;Check(count==2,"Scene roundtrip keeps rendering mode");auto source=scripting::CapturePrefab(w,weapon);auto id=source.at("root").get<std::string>();auto key="prefabs/weapon.prefab.json";Check(SceneSerializer::WriteAtomic(files.project->ResolveAsset(key),source,&error,false),error);auto child=scripting::NewChildPrefab(key);auto changed=source;for(auto& n:changed["entities"])if(n.at("id")==id)n["components"]["MeshRenderer"]["renderMode"]=0;auto delta=scripting::EditPrefabDelta(child,source,changed);Check(scripting::ResolvePrefabDelta(delta,source)!=source,"Prefab inheritance property override");auto childKey="prefabs/child.prefab.json";Check(SceneSerializer::WriteAtomic(files.project->ResolveAsset(childKey),delta,&error,false),error);auto spawn=scripting::SpawnPrefab(restored,childKey,{});Check(restored.GetComponent<MeshRendererComponent>(spawn)->renderMode==MeshRenderMode::World,"Child Prefab mode reaches runtime spawn");
 auto legacy=scene;for(auto& n:legacy["entities"])n["components"]["MeshRenderer"].erase("renderMode");World old;Check(SceneSerializer::RestoreWorld(legacy,old,settings,&error),error);for(auto e:old.Entities())Check(old.GetComponent<MeshRendererComponent>(e)->renderMode==MeshRenderMode::World,"missing property defaults to World");auto descriptor=ComponentRegistry::Builtins().Find("MeshRenderer");Check(descriptor&&descriptor->properties.back().choices==std::vector<std::string>{"World","FirstPerson"},"Inspector choices use ComponentRegistry");Check(!ComponentRegistry::Builtins().Set(w,weapon,ComponentId("MeshRenderer"),"renderMode",42,&error),"invalid mode rejected");
 auto& attachment=w.AddComponent<CameraAttachmentComponent>(weapon);attachment.localPosition={.25f,-.35f,.8f};auto before=w.LocalTransform(weapon);for(float angle:{0.f,.4f,-.7f}){auto pose=RenderPose{};pose.position={2,3+angle,4};pose.rotation=RenderRotation({angle*.2f,angle,0});auto camera=BuildCameraState(pose,CameraComponent{},4.f/3);auto result=CameraAttachmentPose(w,weapon,camera);Check(result&&std::abs(result->position.x-(camera.pose.position.x+camera.right.x*.25f-camera.up.x*.35f+camera.forward.x*.8f))<.001f,"camera rotation and bobbing resolve visual pose");}Check(w.LocalTransform(weapon).position.x==before.position.x,"attachment does not mutate physical Transform");w.DestroyEntity(weapon);auto replacement=Node(w,MeshRenderMode::FirstPerson);gpu.BeginFrame();renderer.Update(w,0);Check(gpu.world==1&&gpu.viewmodel==1,"weapon switch/destroy removes old submissions");renderer.ReleaseGpuResources();renderer.SetRenderAdapter(nullptr);
}
static MeshData Quad(float half=1,float z=0,float u=.5f){MeshData mesh;for(auto p:std::array<std::array<float,3>,4>{{{-half,-half,z},{-half,half,z},{half,half,z},{half,-half,z}}}){MeshVertex v;std::copy(p.begin(),p.end(),v.position);v.normal[2]=-1;v.uv[0]=u;v.uv[1]=.5f;mesh.vertices.push_back(v);}mesh.indices={0,1,2,0,2,3};return mesh;}
static ui::DrawList Hud(unsigned width,unsigned height,RenderTextureHandle texture){ui::DrawList draw;draw.width=float(width);draw.height=float(height);float x=width*.5f,y=height*.5f;for(auto p:std::array<ui::Pair,6>{{{x-8,y-8},{x+8,y-8},{x+8,y+8},{x-8,y-8},{x+8,y+8},{x-8,y+8}}})draw.vertices.push_back({p[0],p[1],.5f,.5f,{1,1,0,1}});draw.commands.push_back({0,6,{0,0,float(width),float(height)},texture});return draw;}
static bool Color(const std::vector<unsigned char>& pixels,unsigned width,unsigned x,unsigned y,int channel){auto at=(size_t(y)*width+x)*4;if(at+3>=pixels.size())return false;return pixels[at+channel]>180&&pixels[at+(channel+1)%3]<65&&pixels[at+(channel+2)%3]<65;}
template<class Adapter>static void Pixels(Adapter& gpu,GlfwWindow& window,const char* backend){ResourceManager resources(nullptr);auto shader=resources.Load<ShaderResource>("dx12/textured.hlsl");auto program=gpu.CreateShaderProgram(shader->GetData());TextureData white;white.pixels={255,255,255,255};auto texture=gpu.CreateTexture2D(white);TextureData colors;colors.width=2;colors.pixels={255,0,0,255,0,255,0,255};auto twoColor=gpu.CreateTexture2D(colors);TextureData middle;middle.pixels={128,128,128,255};auto gray=gpu.CreateTexture2D(middle);auto quad=gpu.UploadMesh(Quad());auto layered=Quad(.45f,.2f,.25f);auto farQuad=Quad(.8f,.7f,.75f);for(auto& v:farQuad.vertices)layered.vertices.push_back(v);for(auto i:farQuad.indices)layered.indices.push_back(i+4);auto compound=gpu.UploadMesh(layered);Check(program.IsValid()&&texture.IsValid()&&quad.IsValid()&&compound.IsValid(),std::string(backend)+" real mesh/shader/texture resources");
 auto draw=[&](RenderMeshHandle mesh,float half,float depth,std::array<float,4> color,RenderTextureHandle image){std::array<float,16> transform{};transform[0]=transform[5]=half;transform[10]=transform[15]=1;transform[14]=depth;gpu.SetTestTransform(transform.data());gpu.SetSurfaceParameters({0,.5f,2,0});gpu.SetBaseColor({1,1,1,1});gpu.SetTestColor(color[0],color[1],color[2],color[3]);gpu.BindShader(program);gpu.BindTexture(0,image);gpu.SetMaterialState({true,false,false});gpu.SetMeshRange({});gpu.DrawMesh(mesh);};
 auto frame=[&](int scenario){window.PollEvents();gpu.BeginFrame();gpu.Clear(0,0,0,1);gpu.BeginMainPass();draw(quad,1,.1f,{0,0,1,1},texture);if(scenario==1)draw(quad,.8f,.7f,{1,0,0,1},texture);if(scenario>=2&&scenario<=5){Check(gpu.BeginViewmodelPass(),std::string(backend)+" viewmodel depth pass");if(scenario==5)draw(quad,.8f,.7f,{.5f,.5f,.5f,1},gray);else if(scenario==2)draw(compound,1,0,{1,1,1,1},twoColor);else {draw(quad,.45f,.2f,{1,0,0,1},texture);draw(quad,.8f,.7f,{0,1,0,1},texture);}gpu.EndViewmodelPass();draw(quad,1,.5f,{1,1,0,1},texture);}gpu.EndMainPass();auto area=gpu.RenderAreaSize();if(scenario==4)gpu.DrawRuntimeUI(Hud(area[0],area[1],texture));gpu.EndFrame();std::vector<unsigned char> pixels;
  if constexpr(requires{gpu.ReadBackFramePixels();})pixels=gpu.ReadBackFramePixels();else pixels=gpu.ReadBackPixels();gpu.Present();return pixels;};
 auto image=frame(0);auto area=gpu.RenderAreaSize();auto w=area[0],h=area[1];Check(Color(image,w,w/2,h/2,2),std::string(backend)+" World mesh visible");image=frame(1);Check(Color(image,w,w/2,h/2,2),std::string(backend)+" World depth occludes ordinary mesh");image=frame(2);Check(Color(image,w,w/2,h/2,0),std::string(backend)+" viewmodel survives wall depth and nearer surface wins within one mesh");Check(Color(image,w,unsigned(w*.8f),h/2,1),std::string(backend)+" farther part visible outside nearer silhouette");Check(Color(image,w,unsigned(w*.95f),h/2,2),std::string(backend)+" World depth preserved after viewmodel pass");image=frame(3);Check(Color(image,w,w/2,h/2,0)&&Color(image,w,unsigned(w*.8f),h/2,1),std::string(backend)+" multiple viewmodel meshes share consistent depth");image=frame(4);auto center=(size_t(h/2)*w+w/2)*4;Check(image[center]>200&&image[center+1]>200&&image[center+2]<50,std::string(backend)+" HUD overlays viewmodels");image=frame(5);center=(size_t(h/2)*w+w/2)*4;Check(std::abs(int(image[center])-61)<=8&&std::abs(int(image[center+1])-61)<=8,std::string(backend)+" textured viewmodel preserves sRGB material tint and output");gpu.DestroyMesh(compound);gpu.DestroyTexture(twoColor);image=frame(0);Check(Color(image,w,w/2,h/2,2),std::string(backend)+" destroyed weapon leaves no image");auto submittedMesh=gpu.UploadMesh(Quad());auto submittedTexture=gpu.CreateTexture2D(white);window.PollEvents();gpu.BeginFrame();gpu.Clear(0,0,0,1);gpu.BeginMainPass();Check(gpu.BeginViewmodelPass(),"post-submit retirement fixture");draw(submittedMesh,.8f,.4f,{1,0,0,1},submittedTexture);gpu.EndViewmodelPass();gpu.EndMainPass();gpu.EndFrame();gpu.DestroyMesh(submittedMesh);gpu.DestroyTexture(submittedTexture);gpu.Present();for(int n=0;n<3;++n)image=frame(0);Check(Color(image,w,w/2,h/2,2),std::string(backend)+" resources destroyed after Submit survive until fence and leave no stale image");glfwSetWindowSize(window.GetGlfwHandle(),420,280);for(int n=0;n<4;++n)image=frame(3);area=gpu.RenderAreaSize();Check(area[0]==420&&area[1]==280&&Color(image,area[0],210,140,0),std::string(backend)+" resize rebuilds viewmodel depth safely");if constexpr(requires{gpu.EnableReadback(false);})gpu.EnableReadback(false);for(int n=0;n<24;++n){window.PollEvents();gpu.BeginFrame();gpu.Clear(0,0,0,1);gpu.BeginMainPass();draw(quad,1,.1f,{0,0,1,1},texture);Check(gpu.BeginViewmodelPass(),"steady GPU frame without readback");draw(quad,.5f,.5f,{1,0,0,1},texture);gpu.EndViewmodelPass();gpu.EndMainPass();gpu.EndFrame();gpu.Present();}if constexpr(requires{gpu.EnableReadback(true);})gpu.EnableReadback(true);gpu.DestroyMesh(quad);gpu.DestroyTexture(texture);gpu.DestroyTexture(gray);for(int n=0;n<3;++n){window.PollEvents();gpu.BeginFrame();gpu.Clear(0,0,0,1);gpu.EndFrame();gpu.Present();}
}
