static void Dx12(){GlfwWindow window;Check(window.Create(320,240,"Viewmodel DX12 regression"),"DX12 window");glfwHideWindow(window.GetGlfwHandle());Dx12RenderAdapter gpu;Check(gpu.Initialize(&window),"DX12 device");Pixels(gpu,window,"DX12");Check(gpu.GetValidationErrorCount()==0,"zero DX12 validation errors");gpu.Shutdown();Check(gpu.Initialize(&window),"DX12 device restart");Pixels(gpu,window,"DX12 restart");Check(gpu.GetValidationErrorCount()==0,"zero restart DX12 validation errors");gpu.Shutdown();}
static Entity Actor(Application& app,const std::string& name,Vec3 position,Vec3 scale,std::array<float,4> tint,MeshRenderMode mode){auto e=app.CreateEmptyEntity(name);auto& t=*app.GetWorld().GetComponent<TransformComponent>(e);t.position=position;t.scale=scale;auto& m=app.GetWorld().AddComponent<MeshRendererComponent>(e);m.meshPath="@engine/models/primitives/cube.obj";m.renderMode=mode;auto& material=app.GetWorld().AddComponent<MaterialComponent>(e);std::copy(tint.begin(),tint.end(),material.tint);return e;}
static void Editor(){Files files;ProjectManager::Activate(files.old);Application app;Check(app.Initialize(Application::StartupMode::ProjectBrowser),"real ImGui editor");SyntheticEditorInput input;glfwHideWindow(dynamic_cast<GlfwWindow*>(app.GetWindow())->GetGlfwHandle());std::string error;Check(app.OpenProject(files.project->descriptorPath,Application::ProjectDecision::Discard,&error),error);auto& e=app.GetEditorLayer();e.SetDiagnosticViewport(400,300);e.SetGridVisible(false);e.SetGameView(true);e.SetUIPreviewVisible(true);app.SetViewportUnlit(true);app.SetEditorCameraPose({0,0,0},0,0);auto settings=app.GetSceneSettings();settings.environment.enabled=false;settings.shadows.enabled=false;settings.antiAliasing=AntiAliasingMode::Off;settings.background.background=EditorBackground::Solid;settings.background.solid={0,0,0};Check(app.SetSceneSettings(settings),"fixture visual settings");auto wall=Actor(app,"Wall",{0,0,2},{10,10,.1f},{0,0,1,1},MeshRenderMode::World);auto weapon=Actor(app,"Weapon",{0,0,3},{1,1,1},{1,0,0,1},MeshRenderMode::World);auto frame=[&](int n=8){app.SetFrameLimit(n);Check(app.Run()==0,"editor frames");};auto* gpu=dynamic_cast<Dx12RenderAdapter*>(app.GetRenderAdapter());frame(20);Check(Color(gpu->ReadBackViewportPixels(),400,200,150,2),"editor ordinary weapon hidden by wall");Check(e.SetProperty(app,weapon,ComponentId("MeshRenderer"),"renderMode",1),e.GetError());frame();Check(Color(gpu->ReadBackViewportPixels(),400,200,150,0),"Inspector mode reaches real Viewmodel GPU pixels");e.UndoEdit(app);frame();Check(Color(gpu->ReadBackViewportPixels(),400,200,150,2),"mode Undo returns to world depth");e.RedoEdit(app);frame();Check(Color(gpu->ReadBackViewportPixels(),400,200,150,0),"mode Redo restores overlay");auto fog=app.CreateEmptyEntity("World Fog");auto& fogSettings=app.GetWorld().AddComponent<FogComponent>(fog);fogSettings.color={0,1,0,1};fogSettings.startDistance=0;fogSettings.endDistance=.2f;fogSettings.density=1;frame();auto fogPixels=gpu->ReadBackViewportPixels();Check(Color(fogPixels,400,200,150,0)&&Color(fogPixels,400,10,10,1),"World fog/HDR uses World depth before unfogged viewmodel composition");Check(e.DeleteEntity(app,fog),e.GetError());frame();auto source=scripting::CapturePrefab(app.GetWorld(),weapon);Check(SceneSerializer::WriteAtomic(files.project->ResolveAsset("prefabs/weapon.prefab.json"),source,&error,false),error);
 auto doc=ui::EmptyDocument();doc.referenceResolution={400,300};ui::Widget panel;panel.id="HUD";panel.type="Panel";panel.parent=doc.root;panel.position={190,140};panel.size={20,20};panel.color={1,1,0,1};doc.widgets.push_back(panel);Check(UILoader::Save("ui/hud.ui.json",doc,&error),error);e.CreateUICanvas(app,"ui/hud.ui.json");frame();auto pixels=gpu->ReadBackViewportPixels();auto center=size_t(150*400+200)*4;Check(pixels[center]>200&&pixels[center+1]>200&&pixels[center+2]<65,"actual Runtime UI Canvas overlays weapon");auto a=app.CreateEmptyEntity("Camera");app.GetWorld().AddComponent<CameraComponent>(a);auto& attach=app.GetWorld().AddComponent<CameraAttachmentComponent>(weapon);attach.localPosition={.25f,-.35f,3};Check(app.SaveSceneAs("Scenes/A.json",false,&error),error);Check(app.SaveSceneAs("Scenes/B.json",false,&error),error);fs::create_directories(files.project->ResolveAsset("scripts"));std::ofstream(files.project->ResolveAsset("scripts/travel.lua"))<<"return {on_update=function(self) if World.get_position(self.entity).x==99 then World.load_scene('Scenes/B.json') end end}";app.GetWorld().AddComponent<LuaScriptComponent>(a).scriptPath="scripts/travel.lua";Check(app.SaveCurrentScene(&error),error);app.SetEditorPlayMode(true);frame(18);Check(app.GetRenderStatistics().viewmodelSubmeshes==1,"Play retains exactly one viewmodel submission");Entity runtimeCamera;for(auto ent:app.GetWorld().Entities())if(app.GetWorld().HasComponent<CameraComponent>(ent))runtimeCamera=ent;auto worldID=app.GetWorld().GetIdentity();app.GetWorld().GetComponent<TransformComponent>(runtimeCamera)->position.x=99;app.GetLuaRuntime().Update(0);frame();Check(app.GetWorld().GetIdentity()!=worldID&&app.GetLevelTravelError().empty()&&app.GetRenderStatistics().viewmodelSubmeshes==1,"Level Travel reloads rendering mode and attachment");Entity noCamera;for(auto ent:app.GetWorld().Entities())if(app.GetWorld().HasComponent<CameraComponent>(ent))noCamera=ent;app.GetWorld().DestroyEntity(noCamera);frame();Check(app.GetRenderStatistics().viewmodelSubmeshes==1&&!app.GetRenderCameraState().entity.IsValid(),"missing active camera uses valid fallback render pose");app.SetEditorPlayMode(false);frame();Check(app.GetWorld().IsAlive(weapon)&&app.GetRenderStatistics().viewmodelSubmeshes==1,"Stop restores authored weapon");Check(e.DeleteEntity(app,weapon),e.GetError());frame();Check(app.GetRenderStatistics().viewmodelSubmeshes==0,"destroyed weapon removed from shared submission");Check(gpu->GetValidationErrorCount()==0,"editor Play/travel/Stop zero DX12 errors");app.Shutdown();}
